21	// readCRDTState reads the next complete text frame, validates the wire format
22	// (compact single-line JSON terminated by one newline, keys type then value)
23	// and decodes the state. Pongs are skipped; a close frame fails the test.
24	func (c *wsClient) readCRDTState() store.CRDTState {
25		c.t.Helper()
26		for {
27			fin, opcode, payload := c.readFrame()
28			switch opcode {
29			case wsOpcodeText:
30				if !fin {
31					c.t.Fatal("server sent a fragmented text frame")
32				}
33				if len(payload) == 0 || payload[len(payload)-1] != '\n' {
34					c.t.Fatalf("state frame is not newline-terminated: %q", payload)
35				}
36				line := string(payload[:len(payload)-1])
37				if strings.ContainsAny(line, "\r\n") {
38					c.t.Fatalf("state frame is not a single line: %q", payload)
39				}
40				if strings.Contains(line, ", ") || strings.Contains(line, ": ") {
41					c.t.Fatalf("state frame is not compact JSON: %q", payload)
42				}
43				var state store.CRDTState
44				if err := json.Unmarshal(payload, &state); err != nil {
45					c.t.Fatalf("text frame is not a crdt state: %s (%v)", payload, err)
46				}
47				return state
48			case wsOpcodePong:
49				continue
50			case wsOpcodeClose:
51				c.t.Fatalf("unexpected close frame while reading state: code=%d", closeCode(payload))
52			default:
53				c.t.Fatalf("unexpected opcode %d while reading state", opcode)
54			}
55		}
56	}
57	
58	// readCRDTRaw reads the raw payload bytes of the next text frame (newline
59	// included), pongs skipped.
60	func (c *wsClient) readCRDTRaw() []byte {
61		c.t.Helper()
62		for {
63			fin, opcode, payload := c.readFrame()
64			if opcode == wsOpcodePong {
65				continue
66			}
67			if opcode != wsOpcodeText || !fin {
68				c.t.Fatalf("unexpected opcode=%d fin=%v", opcode, fin)
69			}
70			return payload
71		}
72	}
