138			{"unknown session", http.MethodGet, "/v1/sessions/ghost/documents/doc/crdt/state/subscribe", true, http.StatusNotFound},
139			{"revoked permission", http.MethodGet, "/v1/sessions/sess/documents/doc2/crdt/state/subscribe", true, http.StatusForbidden},
