		t.Fatalf("state after restart = %d %q", rec.Code, rec.Body.String())
	}
	assertJSONError(t, read(sessionCRDTStatePath("sess", "doc-empty")), http.StatusNotFound)
	assertJSONError(t, read(sessionCRDTStatePath("ghost", "doc")), http.StatusNotFound)
	assertJSONError(t, read(sessionCRDTStatePath("sess-rev", "doc-rev")), http.StatusForbidden)
